// 3 Production Implementations of Bounded Concurrency

// ==========================================================
// APPROACH 1: Optimal Worker Pool / Sliding Window
// Time: O(N) | Space: O(K) active promises
// ==========================================================
export async function mapConcurrentPool(items, limit, asyncFn) {
  const results = new Array(items.length);
  let nextIndex = 0;

  async function worker() {
    while (nextIndex < items.length) {
      const currentIndex = nextIndex++;
      results[currentIndex] = await asyncFn(items[currentIndex], currentIndex);
    }
  }

  // Spawn exactly 'limit' workers running concurrently
  const workers = Array.from({ length: Math.min(limit, items.length) }, () => worker());
  await Promise.all(workers);
  return results;
}

// ==========================================================
// APPROACH 2: Batch Chunking Pattern
// Time: O(N) | Space: O(K)
// ==========================================================
export async function mapConcurrentChunks(items, chunkSize, asyncFn) {
  const results = [];
  for (let i = 0; i < items.length; i += chunkSize) {
    const chunk = items.slice(i, i + chunkSize);
    const chunkResults = await Promise.all(chunk.map(asyncFn));
    results.push(...chunkResults);
  }
  return results;
}

// ==========================================================
// APPROACH 3: Reusable Async Semaphore Pattern
// ==========================================================
export class AsyncSemaphore {
  constructor(maxConcurrency) {
    this.maxConcurrency = maxConcurrency;
    this.currentRunning = 0;
    this.waitingQueue = [];
  }

  async acquire() {
    if (this.currentRunning < this.maxConcurrency) {
      this.currentRunning++;
      return;
    }
    await new Promise(resolve => this.waitingQueue.push(resolve));
    this.currentRunning++;
  }

  release() {
    this.currentRunning--;
    if (this.waitingQueue.length > 0) {
      const nextResolve = this.waitingQueue.shift();
      nextResolve();
    }
  }

  async run(taskFn) {
    await this.acquire();
    try {
      return await taskFn();
    } finally {
      this.release();
    }
  }
}

// Production Exponential Backoff with Full Jitter & Idempotent Headers
export async function retryWithBackoffAndJitter(
  operationFn,
  options = { maxRetries: 3, baseDelayMs: 200, maxDelayMs: 5000 }
) {
  let attempt = 0;

  while (attempt < options.maxRetries) {
    try {
      return await operationFn(attempt);
    } catch (error) {
      attempt++;
      if (attempt >= options.maxRetries) {
        console.error(`❌ Max retries (${options.maxRetries}) reached. Failing permanently.`);
        throw error;
      }

      // Exponential Backoff with Full Jitter Formula
      const exponentialCap = Math.min(
        options.maxDelayMs,
        options.baseDelayMs * Math.pow(2, attempt)
      );
      const sleepTime = Math.round(Math.random() * exponentialCap);

      console.warn(`⚠️ Attempt ${attempt} failed. Retrying in ${sleepTime}ms with jitter...`);
      await new Promise(resolve => setTimeout(resolve, sleepTime));
    }
  }
}

// Fundamental Express.js Server Setup & REST Route Handlers
import express from 'express';

const app = express();
const PORT = process.env.PORT || 3000;

// 1. Built-in JSON Body Parser Middleware
app.use(express.json());

// In-memory data store for demonstration
let products = [
  { id: 'prod_1', name: 'Mechanical Keyboard', price: 120, stock: 15 }
];

// 2. REST Route Handlers
// GET /api/v1/products - Filtering via Query Parameters
app.get('/api/v1/products', (req, res) => {
  const maxPrice = Number(req.query.maxPrice);
  let results = products;

  if (!isNaN(maxPrice)) {
    results = results.filter(p => p.price <= maxPrice);
  }

  res.status(200).json({ success: true, count: results.length, data: results });
});

// GET /api/v1/products/:id - Route Parameters
app.get('/api/v1/products/:id', (req, res) => {
  const product = products.find(p => p.id === req.params.id);
  if (!product) {
    return res.status(404).json({ success: false, error: 'Product Not Found' });
  }
  res.status(200).json({ success: true, data: product });
});

// POST /api/v1/products - Creating Resources (201 Created)
app.post('/api/v1/products', (req, res) => {
  const { name, price, stock } = req.body;

  if (!name || typeof price !== 'number') {
    return res.status(400).json({ success: false, error: 'Name and numeric price are required' });
  }

  const newProduct = { id: `prod_${Date.now()}`, name, price, stock: stock || 0 };
  products.push(newProduct);

  res.status(201).json({ success: true, data: newProduct });
